#include "robot.h"

#if PWM_CONTROLLER_TYPE == ESP32PWM
/**
 * Servo PWM generated by the ESP32 LEDC hardware peripheral.
 *
 * This replaces ESP32_ISR_Servo, which bit-banged every servo pin from a
 * hardware timer interrupt firing every few microseconds. That approach
 * fights the WiFi stack for CPU time and interrupt latency (and stalls
 * whenever the flash cache is disabled, e.g. during WiFi/NVS/EEPROM writes),
 * which is what caused servo jitter and instability together with WiFi and
 * websockets on newer cores. LEDC produces the pulses fully in hardware, so
 * WiFi load has no effect on servo timing and no CPU time is spent on PWM.
 *
 * The ESP32 has 16 LEDC channels, so up to 16 servos can be driven directly
 * (the quadruped uses 12). Use a PCA9685 for more.
 */

#ifndef ESP32PWM_SERVO_FREQ
	#define ESP32PWM_SERVO_FREQ 50   // Hz, standard analog servo frame (20ms)
#endif
#ifndef ESP32PWM_SERVO_RESOLUTION
	#define ESP32PWM_SERVO_RESOLUTION 16   // bits, ~0.3us per step at 50Hz
#endif

#define ESP32PWM_SERVO_PERIOD_US (1000000UL / ESP32PWM_SERVO_FREQ)
#define ESP32PWM_SERVO_COUNT     (LEG_NUM * LEG_DOF)

#ifdef SOC_LEDC_SUPPORT_HS_MODE
	#define ESP32PWM_LEDC_CHANNELS (SOC_LEDC_CHANNEL_NUM * 2)   // high + low speed groups
#else
	#define ESP32PWM_LEDC_CHANNELS SOC_LEDC_CHANNEL_NUM
#endif

#if ESP32PWM_SERVO_COUNT > ESP32PWM_LEDC_CHANNELS
	#error "Not enough LEDC channels for all servos, use PCA9685 instead"
#endif

class LedcServoBus : public ServoBus {
	public:
		const char *name() const override { return "ESP32 LEDC " ; }

		bool begin(const uint8_t *channels, uint8_t count) override
		{
			Serial.printf("%uHz/%ubit ", ESP32PWM_SERVO_FREQ, ESP32PWM_SERVO_RESOLUTION);
			bool ok = true;
			_count = count;
			for (uint8_t i = 0; i < count; i++) {
				_pins[i] = channels[i];
				if (!ledcAttach(_pins[i], ESP32PWM_SERVO_FREQ, ESP32PWM_SERVO_RESOLUTION)) {
					Serial.printf("LEDC attach failed for pin %u\n", _pins[i]);
					ok = false;
					continue;
				}
				ledcWrite(_pins[i], 0);   // no pulses until the first position is known
			}
			return ok;
		}

		void write(uint8_t index, uint16_t us) override
		{
			if (index >= _count) {
				return;
			}
			if (!_enabled || us == 0) {
				ledcWrite(_pins[index], 0);
				return;
			}
			if (us < SERVO_MIN) us = SERVO_MIN;
			if (us > SERVO_MAX) us = SERVO_MAX;
			ledcWrite(_pins[index], ((uint32_t)us << ESP32PWM_SERVO_RESOLUTION) / ESP32PWM_SERVO_PERIOD_US);
		}

		// Disabled: stop sending pulses, servos go limp. Pulses come back on the next write.
		void setEnabled(bool enabled) override
		{
			_enabled = enabled;
			if (!enabled) {
				for (uint8_t i = 0; i < _count; i++) {
					ledcWrite(_pins[i], 0);
				}
			}
		}

		uint8_t channelLimit() const override { return 40; }   // GPIO numbers

		const char *checkChannel(uint8_t pin) const override
		{
			switch (pin) {
				case 0: case 2: case 5: case 12: case 15:
					return "strapping pin, the board may fail to boot";
				case 34: case 35: case 36: case 37: case 38: case 39:
					return "input only pin";
			}
			return nullptr;
		}

	private:
		uint8_t _pins[ESP32PWM_SERVO_COUNT] = {};
		uint8_t _count   = 0;
		bool    _enabled = true;
};

ServoBus &servoBus()
{
	static LedcServoBus bus;
	return bus;
}
#endif
